class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Maximum cells available on the deck
        max_cells = n * n
        # Maximum containers allowed by weight capacity
        max_by_weight = maxWeight // w
        # The answer is the smaller of the two limits
        return min(max_cells, max_by_weight)
